  Lemma vo_s5 : forall (msF4 : machine_state) (mo4 : Model) (sk4 : as_St H) (m4 : mem) (R4 : bvmap 5 word) (pid' : bptr) (A : Z)
                       (jA : list byte),
    as_VIS H sk4 msF4 = MS R4 F (Z_to_bv 64 0xfb6c4) fc None m4 (seg_rom asegs) -> rfull R4 ->
    getr R4 2 = Z_to_bv 64 (spz - 96) -> getr R4 3 = gp -> getr R4 4 = tp -> getr R4 8 = Z_to_bv 64 (v + 8) ->
    getr R4 9 = Z_to_bv 64 v -> getr R4 18 = Z_to_bv 64 (v + 16) -> getr R4 20 = Z_to_bv 64 (20 * cap') ->
    getr R4 21 = Z_to_bv 64 A -> getr R4 22 = Z_to_bv 64 (A + 20 * cap) -> getr R4 23 = Z_to_bv 64 (sh v) ->
    getr R4 24 = Z_to_bv 64 (sh (v + 8)) -> getr R4 25 = Z_to_bv 64 (sh (v + 16)) -> getr R4 26 = s10 -> getr R4 27 = s11 ->
    as_AKREL H sk4 (mkCfg msF4 mo4) -> as_MPRES H mo mo4 ->
    vo_mid sk4 m4 pid' A vo_X0 -> ablock_range H A (20 * cap') -> ~ In pid' (map blk_id LB) ->
    rw_cells asegs m4 A [CB (Z.to_nat (20 * cap)) jA] ->
    SHAD m4 A (cc_gen (20 * cap') (20 * cap')) -> (0 < cap -> SHAD m4 b (cc_gen (20 * cap) (20 * cap))) ->
