  Lemma vo_s4 : forall (msF3 : machine_state) (mo3 : Model) (sk3 : as_St H) (m3 : mem) (R3 : bvmap 5 word) (pid' : bptr) (A : Z)
                       (jA : list byte),
    as_VIS H sk3 msF3 = MS R3 F (Z_to_bv 64 0xfb694) fc None m3 (seg_rom asegs) -> rfull R3 ->
    getr R3 2 = Z_to_bv 64 (spz - 96) -> getr R3 3 = gp -> getr R3 4 = tp ->
    getr R3 8 = Z_to_bv 64 (v + 8) -> getr R3 9 = Z_to_bv 64 v -> getr R3 18 = Z_to_bv 64 (v + 16) -> getr R3 20 = Z_to_bv 64 (20 * cap') ->
    getr R3 21 = Z_to_bv 64 A -> getr R3 22 = Z_to_bv 64 (A + 20 * cap) -> getr R3 23 = Z_to_bv 64 (sh v) ->
    getr R3 24 = Z_to_bv 64 (sh (v + 8)) -> getr R3 25 = Z_to_bv 64 (sh (v + 16)) -> getr R3 26 = s10 -> getr R3 27 = s11 ->
    as_AKREL H sk3 (mkCfg msF3 mo3) -> as_MPRES H mo mo3 ->
    vo_mid sk3 m3 pid' A [] -> ablock_range H A (20 * cap') -> ~ In pid' (map blk_id LB) ->
    rw_cells asegs m3 A [CB (Z.to_nat (20 * cap)) jA] ->
    SHAD m3 A (cc_gen (20 * cap') (20 * cap')) ->
