  Lemma vo_s3 : forall (msF2 : machine_state) (mo2 : Model) (sk2 : as_St H) (m2 : mem) (R2 : bvmap 5 word) (pid' : bptr) (A : Z)
                       (jall : list byte),
    as_VIS H sk2 msF2 = MS R2 F (Z_to_bv 64 0xfb67c) fc None m2 (seg_rom asegs) -> rfull R2 ->
    getr R2 2 = Z_to_bv 64 (spz - 96) -> getr R2 3 = gp -> getr R2 4 = tp -> getr R2 8 = Z_to_bv 64 (v + 8) ->
    getr R2 9 = Z_to_bv 64 v -> getr R2 10 = Z_to_bv 64 A -> getr R2 18 = Z_to_bv 64 (v + 16) -> getr R2 19 = Z_to_bv 64 src ->
    getr R2 20 = Z_to_bv 64 (20 * cap') -> getr R2 22 = Z_to_bv 64 (20 * cap) -> getr R2 23 = Z_to_bv 64 (sh v) ->
    getr R2 24 = Z_to_bv 64 (sh (v + 8)) -> getr R2 25 = Z_to_bv 64 (sh (v + 16)) -> getr R2 26 = s10 -> getr R2 27 = s11 ->
    as_AKREL H sk2 (mkCfg msF2 mo2) -> as_MPRES H mo mo2 ->
    vo_mid sk2 m2 pid' A [] -> ablock_range H A (20 * cap') -> ~ In pid' (map blk_id LB) ->
    rw_cells asegs m2 A [CB (Z.to_nat (20 * cap')) jall] -> addressable m2 A (20 * cap') ->
